        # 重叠（相邻端点可接）。键序/容器/项数/字段/重叠判 INPUT，未知 id
        # 留执行期判 BACKEND。
        if list(raw_op) != ["op", "items"]:
            fail(EXIT_INPUT, "INPUT")
        raw_items = raw_op["items"]
        if (
            not isinstance(raw_items, list)
            or isinstance(raw_items, bool)
